import{at as e,it as t,n,vt as r}from"./chunks/framework.DdRMjwGS.js";var i=JSON.parse(`{"title":"配置说明","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/configuration.md","filePath":"zh/guide/configuration.md"}`),a={name:`zh/guide/configuration.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="配置说明" tabindex="-1">配置说明 <a class="header-anchor" href="#配置说明" aria-label="Permalink to “配置说明”">​</a></h1><p>本文档对应 Zotero PDF2zh <strong>v4.1.1</strong>（含 v4.1.0 功能）。</p><h2 id="插件设置" tabindex="-1">插件设置 <a class="header-anchor" href="#插件设置" aria-label="Permalink to “插件设置”">​</a></h2><p>在 Zotero 中打开「工具 → PDF2zh 首选项」。</p><h3 id="python-server-ip" tabindex="-1">Python Server IP <a class="header-anchor" href="#python-server-ip" aria-label="Permalink to “Python Server IP”">​</a></h3><ul><li>默认：<code>http://127.0.0.1:8890</code></li><li>如果修改了 <code>server.py --port</code>，同步修改端口。</li><li>Server v4.1.0 默认只监听 <code>127.0.0.1</code>。远程部署时需要显式启动：</li></ul><div class="language-shell" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0.0.0</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">远程访问</p><p><code>0.0.0.0</code> 会允许网络中的其他设备访问 Server。请同时配置防火墙，并只在明确需要时启用。</p></div><h3 id="翻译引擎" tabindex="-1">翻译引擎 <a class="header-anchor" href="#翻译引擎" aria-label="Permalink to “翻译引擎”">​</a></h3><table tabindex="0"><thead><tr><th>对比项</th><th>pdf2zh 1.x</th><th>pdf2zh_next 2.x</th></tr></thead><tbody><tr><td>状态</td><td>旧版兼容</td><td><strong>推荐</strong></td></tr><tr><td>配置文件</td><td><code>config.json</code></td><td><code>config.toml</code></td></tr><tr><td>自定义字体</td><td>支持</td><td>主要使用上游字体选择</td></tr><tr><td>Dual 模式</td><td>基础支持</td><td>LR 同页左右 / TB 交替页</td></tr><tr><td>OCR / 表格 / 术语</td><td>功能较少</td><td>功能更完整</td></tr><tr><td>DeepSeek V4 Thinking</td><td>不适用</td><td>v2.9.0+ 支持</td></tr></tbody></table><p>除非依赖旧版特性，推荐使用 <strong>pdf2zh_next</strong>。</p><h3 id="wenyi-引擎-第一版" tabindex="-1">Wenyi 引擎（第一版） <a class="header-anchor" href="#wenyi-引擎-第一版" aria-label="Permalink to “Wenyi 引擎（第一版）”">​</a></h3><p>可选的整篇翻译引擎，仅支持有文本层的完整 PDF，可输出单语和左右并列的双语 PDF； 不支持裁剪、单独的对照操作、跳页和 OCR。切回 PDF2zh 时原有设置保留。</p><ol><li>同步更新插件和 Server，在翻译引擎中选择 <strong>Wenyi</strong>。</li><li>在 <strong>LLM API 配置管理</strong>中添加并激活 <strong>DeepSeek</strong>，填写密钥并设置思考模式和推理强度。 模型固定为 <code>deepseek-flash</code>，不使用该配置的模型名、API URL 或其他额外参数， 也不回退到 Server 的密钥环境变量。未设置思考参数时使用关闭 / 高。</li><li>正常启动 Server（<code>python server.py</code>）后翻译 PDF。首次使用会自动创建专用 Python 3.12 环境 <code>zotero-wenyi-venv</code>，从 PyPI 或所选镜像安装最新稳定版 Wenyi 包， 并启动本机 bridge；无需手工安装。首次安装和模型资源下载可能较慢。</li></ol><p><strong>翻译流程配置</strong>中的<strong>翻译文体</strong>下拉框默认为<strong>学术</strong>（<code>academic</code>）， 翻译文学文本时可切换为<strong>文学</strong>（<code>literary</code>）。选择保存在插件中，通过子命令前的 <code>--prompt-genre</code> 传给 CLI，不写入 YAML，也不改变 CLI 自身的默认文体。</p><p>勾选复选框即可开启对应阶段，取消勾选即可关闭。 全书预扫、译文润色和全书审校默认勾选，三译合润默认不勾选。 三译合润生成三份译稿再合成润色，开启时锁定润色，关闭后恢复原先选择。 这些阶段会增加耗时和用量；关闭阶段可节省成本，但会减少上下文或质量检查。 思考参数只在 LLM 配置中设置，不再重复显示。</p><p><strong>注释/链接对齐</strong>默认关闭，对应 CLI 的注释和链接定位阶段 （<code>pipeline.annotation_alignment</code>），不控制 PDF 页面几何布局或左右拼页。</p><p><strong>默认生成文件</strong>中单语默认开启，双语默认关闭。可以任选一种或同时生成两种， 但至少需要选择一种；每种文件的<strong>生成后自动打开</strong>沿用 PDF2zh 对应文件类型的选项， Wenyi 的生成选项则独立保存，不覆盖 PDF2zh 的生成设置。 开启双语后可选择<strong>双语顺序（从左到右）</strong>：默认<strong>译文在前</strong>，即左侧译文、右侧原文； 选择<strong>原文在前</strong>则相反。关闭双语后仍保留已选顺序，供下次使用。 这需要 Wenyi CLI 支持将 <code>output.bilingual_order</code> 应用于 PDF 导出； 旧版 CLI 固定原文在左，需要更新后才能使用顺序选项。</p><p>密钥仅注入本次 CLI 子进程，不写入任务文件或交给 bridge。请只连接可信 Server， 远程连接使用 HTTPS。CLI 与 AGPL BabelDOC bridge 保持独立进程，通过 HTTP 通信。 环境维护见<a href="./package-update.html#wenyi-独立环境">引擎包更新</a>。</p><p>需要手工管理时，使用 <code>--wenyi-python /path/to/environment/python</code> 指定安装了 <code>wenyi-cli</code> 和 <code>wenyi-core</code> 的 Python，使用 <code>--wenyi-bridge-url</code> 指定外部 bridge； 只指定后者仍使用托管 CLI。设置 <code>--enable_venv=False</code> 时，未指定 <code>--wenyi-python</code> 则使用 Server 自身的 Python，外部 bridge 默认 <code>http://127.0.0.1:8765</code>。 <code>--wenyi-timeout</code> 默认 10800 秒，不含环境准备时间。 所选安装必须支持 Core 的运行时 bridge 连接 API（<code>wenyi_core.pdf_bridge.connection</code>）； 不支持时明确提示更新环境或选择正确解释器，不回退到其他 CLI 或端口。</p><h4 id="检查点与再次提交" tabindex="-1">检查点与再次提交 <a class="header-anchor" href="#检查点与再次提交" aria-label="Permalink to “检查点与再次提交”">​</a></h4><p>任务完成前请保持 Server 运行。中断后，使用相同源/目标语言和数据根目录再次提交同一份 PDF，即可接续 Core 检查点。每次提交仍创建新任务 ID，以及独立的进度/结果回执、 配置、日志和输出，不会在任务列表中重新打开旧任务。进度百分比表示当前阶段， 没有单独的恢复/取消界面。</p><p>插件按 SHA256 识别 PDF，向 Core 传递内部统一命名为 <code>source.pdf</code> 的原样副本， 不改写上传原文。改名不丢失检查点；即使文件名相同，不同内容也不共用翻译状态。 显式源语言与自动检测分别保存；<code>zh-CN</code> 和 <code>zh</code> 归一为同一目标语言，不同目标语言 由 Core 的目标目录和运行锁隔离。仅支持完整 PDF：跳页、OCR 和页面选择请求在执行前拒绝。 修改流程/模型选项不会强制重译已完成的译文。</p><p>Server 按需以新的本机随机端口启动托管 bridge，专用 launcher 将抽取和导出请求解析到 本次地址，不改变保存的 source hash、session ID、paragraph IDs、pages 和冻结版式快照。 状态中的 <code>zotero-wenyi://bridge</code> 是不可联网的逻辑身份，不是服务 URL； 不要用独立 CLI 直接执行生成的任务配置。没有 launcher/resolver 时它不能用于 HTTP。 独立 Wenyi CLI 行为不变。外部 bridge 须自行保持相同的持久 <code>WENYI_BABELDOC_STATE_DIR</code>。session 缺失或不兼容时明确失败， 不会静默重新抽取以替换旧段落映射。</p><h4 id="数据根目录与可清理缓存" tabindex="-1">数据根目录与可清理缓存 <a class="header-anchor" href="#数据根目录与可清理缓存" aria-label="Permalink to “数据根目录与可清理缓存”">​</a></h4><p>Wenyi 数据仅归本插件所有，不放在 Server 安装目录中，也不共享 Wenyi Desktop/CLI/Web 项目。用 <code>--wenyi-data-dir</code> 或 <code>ZOTERO_WENYI_DATA_DIR</code> 设置，命令行优先。默认位置：</p><ul><li>Linux：<code>$XDG_DATA_HOME/zotero-pdf2zh/wenyi</code>，未设置则为 <code>~/.local/share/zotero-pdf2zh/wenyi</code>。</li><li>macOS：<code>~/Library/Application Support/zotero-pdf2zh/wenyi</code>。</li><li>Windows：<code>%LOCALAPPDATA%\\zotero-pdf2zh\\wenyi</code>，未设置则使用用户目录下的 <code>AppData\\Local</code>。</li></ul><table tabindex="0"><thead><tr><th>数据根目录内路径</th><th>职责与保留规则</th></tr></thead><tbody><tr><td><code>translations/</code></td><td>持久 Core 检查点、源文产物、术语和锁；续译需要保留。</td></tr><tr><td><code>bridge/sessions/</code></td><td>托管 bridge 的源 PDF、冻结版式/session 快照；恢复导出必需，<strong>不是可清理缓存</strong>，应与 <code>translations/</code> 一起备份。</td></tr><tr><td><code>tasks/&lt;task-id&gt;/</code></td><td>上传 PDF、内部输入副本、任务配置、回执、日志及输出 PDF；所有使用它的任务停止后，可手工清理已结束 attempt，再次提交会提供新副本。</td></tr><tr><td><code>runtime/</code></td><td>托管 bridge 诊断日志，不是翻译状态。</td></tr><tr><td><code>cache/</code></td><td>默认存放可下载的字体、模型和分词器资源；停止运行后可清理，缺失资源会重新下载。</td></tr></tbody></table><p>用 <code>--wenyi-cache-dir</code> 或 <code>ZOTERO_WENYI_CACHE_DIR</code> 覆盖缓存位置，命令行优先。 缓存不能与检查点、任务、session 或运行时目录重叠，也不能包含数据根目录。 缓存设置仅注入 Wenyi CLI/托管 bridge 子进程，不修改 PDF2zh 或 Server 的全局缓存设置； 外部 bridge 自行管理资源缓存。专用 Python 环境仍属于安装管理范围 （<code>server/zotero-wenyi-venv/</code>），发布给附件下载的副本仍位于既有 <code>server/translated/</code> 下载目录。</p><p>不自动清理、迁移或发现旧 <code>server/wenyi-tasks/</code>、<code>server/wenyi-runtime/</code> 及 Desktop/CLI/Web 数据。更换数据根目录即选择独立状态；要继续翻译请保持相同路径。不要把缓存指向包含其他数据的目录。 仅数据所有者可在 Server/bridge 停止后手工清理；仍需续译/导出时先备份。 这些目录包含私有文档和日志，不要整体上传。不要用尚未支持 Wenyi 的上游 Server 包覆盖此适配版。</p><h2 id="llm-api-配置" tabindex="-1">LLM API 配置 <a class="header-anchor" href="#llm-api-配置" aria-label="Permalink to “LLM API 配置”">​</a></h2><p>在「LLM API 配置管理」中新增或编辑服务。</p><p>常用字段：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>Service</td><td>翻译服务类型</td></tr><tr><td>Model</td><td>模型名称</td></tr><tr><td>Base URL</td><td>API 基础地址</td></tr><tr><td>API Key</td><td>密钥</td></tr><tr><td>Extra Parameters</td><td>服务特定的 <code>extraData</code> 参数</td></tr></tbody></table><p>v4.1.0 的编辑器支持<strong>获取模型列表</strong>。在线获取的模型会与插件默认模型、用户历史模型合并并去重；获取失败不会清空默认列表。</p><h3 id="api-key-日志" tabindex="-1">API Key 日志 <a class="header-anchor" href="#api-key-日志" aria-label="Permalink to “API Key 日志”">​</a></h3><p>插件和 Server 日志会对 API Key / token / secret 等敏感字段脱敏，不会在正常 Debug Log 中打印明文密钥。</p><h2 id="deepseek" tabindex="-1">DeepSeek <a class="header-anchor" href="#deepseek" aria-label="Permalink to “DeepSeek”">​</a></h2><p>v4.1.0 默认提供：</p><ul><li><code>deepseek-v4-flash</code></li><li><code>deepseek-v4-pro</code></li></ul><p>旧的 <code>deepseek-chat</code> / <code>deepseek-reasoner</code> 不再作为可选项显示。已有配置会自动迁移：</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>deepseek-chat</span></span>
<span class="line"><span>→ deepseek-v4-flash + thinking=disabled</span></span>
<span class="line"><span></span></span>
<span class="line"><span>deepseek-reasoner</span></span>
<span class="line"><span>→ deepseek-v4-flash + thinking=enabled + effort=high</span></span></code></pre></div><h3 id="thinking-mode" tabindex="-1">Thinking Mode <a class="header-anchor" href="#thinking-mode" aria-label="Permalink to “Thinking Mode”">​</a></h3><p>PDF 翻译默认：</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Thinking Mode = Disabled</span></span></code></pre></div><p>开启后可选：</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Reasoning Effort = high / max</span></span></code></pre></div><p>Thinking Control 需要实际 <code>pdf2zh_next</code> runtime 支持。默认不思考时，旧环境仍可翻译；只有用户手动开启思考且 runtime 不支持时，Server 才会在 API 请求前停止。详见 <a href="/zh/guide/extra-params.html">额外参数</a> 与 <a href="/zh/guide/package-update.html">翻译环境更新</a>。</p><h2 id="qps-与-pool-size" tabindex="-1">QPS 与 Pool Size <a class="header-anchor" href="#qps-与-pool-size" aria-label="Permalink to “QPS 与 Pool Size”">​</a></h2><ul><li><strong>QPS</strong>：限制翻译请求发送速率。</li><li><strong>Pool Size</strong>：限制并发 Worker 数。</li><li><strong>Pool Size = 0（推荐）</strong>：不显式指定 <code>pool_max_workers</code>，交给 <code>pdf2zh_next</code> 根据 QPS 处理。</li></ul><p>旧版的 <code>pool size = qps × 10</code> 已废弃，不要继续使用。</p><h2 id="dual-pdf-布局" tabindex="-1">Dual PDF 布局 <a class="header-anchor" href="#dual-pdf-布局" aria-label="Permalink to “Dual PDF 布局”">​</a></h2><h3 id="side-by-side-lr" tabindex="-1">Side by Side / LR <a class="header-anchor" href="#side-by-side-lr" aria-label="Permalink to “Side by Side / LR”">​</a></h3><p>同一页左右排列。</p><p>默认顺序使用上游原文优先行为，通常是：</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>原文 | 译文</span></span></code></pre></div><p>开启「译文在前」后顺序相反。</p><h3 id="alternating-pages-tb" tabindex="-1">Alternating Pages / TB <a class="header-anchor" href="#alternating-pages-tb" aria-label="Permalink to “Alternating Pages / TB”">​</a></h3><p>原文页与译文页交替出现。</p><div class="info custom-block"><p class="custom-block-title">旧文案</p><p>历史 UI 曾把 TB 写成 “Top &amp; Bottom / 上下对照”，但当前含义是 <strong>Alternating Pages</strong>，不是在同一页上下排版。</p></div><h2 id="pdf-后处理操作" tabindex="-1">PDF 后处理操作 <a class="header-anchor" href="#pdf-后处理操作" aria-label="Permalink to “PDF 后处理操作”">​</a></h2><p>v4.1.0 会识别附件状态，避免重复处理：</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>origin</span></span>
<span class="line"><span>→ mono / dual(LR/TB)</span></span>
<span class="line"><span>→ mono-cut / dual-cut / compare / crop-compare</span></span></code></pre></div><p><code>compare</code> 与 <code>crop-compare</code> 是终态；对结果文件再次执行同一操作会直接提示，不会再次上传/生成重复附件。</p><p>LR dual 执行 Crop 或 Crop-Compare 时，Server 会先内部转换为适合处理的 TB 结构，然后继续完成真正的 <code>dual-cut</code> / <code>crop-compare</code>，不会把“LR→TB”错误当成最终结果。</p><p>详见 <a href="/zh/guide/translation-options.html">翻译选项</a>。</p><h2 id="其他-pdf2zh-next-选项" tabindex="-1">其他 pdf2zh_next 选项 <a class="header-anchor" href="#其他-pdf2zh-next-选项" aria-label="Permalink to “其他 pdf2zh_next 选项”">​</a></h2><h3 id="仅保留实际翻译页面" tabindex="-1">仅保留实际翻译页面 <a class="header-anchor" href="#仅保留实际翻译页面" aria-label="Permalink to “仅保留实际翻译页面”">​</a></h3><p>仅在指定页码范围时有意义，例如使用「跳过最后几页」后，只保留实际参与翻译的页面。</p><h3 id="ocr-workaround" tabindex="-1">OCR Workaround <a class="header-anchor" href="#ocr-workaround" aria-label="Permalink to “OCR Workaround”">​</a></h3><p>该选项主要改善已经具有文字层的特殊/扫描类 PDF 的兼容性，并不是完整 OCR 引擎。</p><h3 id="增强兼容性" tabindex="-1">增强兼容性 <a class="header-anchor" href="#增强兼容性" aria-label="Permalink to “增强兼容性”">​</a></h3><p>只建议在遇到渲染或文字层异常时开启。上游兼容模式可能同时改变部分布局/页序策略。</p><h3 id="无水印" tabindex="-1">无水印 <a class="header-anchor" href="#无水印" aria-label="Permalink to “无水印”">​</a></h3><p>Zotero PDF2zh 默认生成无水印输出；Server 会将设置传给 <code>pdf2zh_next</code>。</p><h2 id="配置文件迁移" tabindex="-1">配置文件迁移 <a class="header-anchor" href="#配置文件迁移" aria-label="Permalink to “配置文件迁移”">​</a></h2><p>v4.1.0 不再每次启动都用 <code>.example</code> 覆盖用户配置。</p><p>Server 会：</p><ul><li>保留已有用户值；</li><li>保留未知自定义字段；</li><li>只补充新版缺失的默认字段；</li><li>更新项目托管的 <code>venv.json</code> package 约束，同时保留用户额外添加的包；</li><li>旧配置无法解析时先备份为 <code>.invalid.bak</code>。</li></ul><p>当前 <code>config.toml.example</code> 以 <code>pdf2zh_next 2.9.0</code> schema 为基线，同时保留 Zotero PDF2zh 自己的安全默认，例如 DeepSeek V4、无水印和 <code>zh-CN</code>。</p><h2 id="server-命令行参数" tabindex="-1">Server 命令行参数 <a class="header-anchor" href="#server-命令行参数" aria-label="Permalink to “Server 命令行参数”">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>--host</code></td><td><code>127.0.0.1</code></td><td>监听地址</td></tr><tr><td><code>--port</code></td><td><code>8890</code></td><td>Server 端口</td></tr><tr><td><code>--enable_venv</code></td><td><code>True</code></td><td>托管翻译环境</td></tr><tr><td><code>--env_tool</code></td><td><code>auto</code></td><td>沿用已有 uv/conda；新环境优先 uv</td></tr><tr><td><code>--check_update</code></td><td><code>True</code></td><td>启动时检查 Server 更新</td></tr><tr><td><code>--update_source</code></td><td><code>gitee</code></td><td>优先源 <code>gitee</code> / <code>github</code>；两个都会尝试</td></tr><tr><td><code>--enable_mirror</code></td><td><code>True</code></td><td>自动优化 Python 包下载源</td></tr><tr><td><code>--enable_winexe</code></td><td><code>False</code></td><td>Windows standalone exe 模式</td></tr><tr><td><code>--skip_install</code></td><td><code>False</code></td><td>禁止自动创建/修复翻译环境</td></tr></tbody></table><p>示例：</p><div class="language-shell" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 普通用户</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server.py</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 强制 conda</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env_tool=conda</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 强制 uv</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env_tool=uv</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 优先用 GitHub 更新源（失败会自动试 Gitee）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --update_source=github</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 局域网访问（高级）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0.0.0</span></span></code></pre></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="/zh/guide/installation.html">安装指南</a></li><li><a href="/zh/guide/translation-options.html">翻译选项</a></li><li><a href="/zh/guide/extra-params.html">额外参数</a></li><li><a href="/zh/guide/package-update.html">翻译环境更新</a></li></ul>`,86)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};